// Checks that the delivery came from Reelsaw (Standard Webhooks, https://www.standardwebhooks.com):
// webhook-signature holds "v1,<base64 HMAC-SHA256 of `${webhook-id}.${webhook-timestamp}.${raw body}`>",
// keyed with the base64 part of the whsec_ secret. Deliveries older than 5 minutes are refused (replays).
//
// The signing secret: paste the whsec_… value Reelsaw showed when you added the webhook below, or (self-hosted
// n8n) set the environment variable REELSAW_WEBHOOK_SECRET. During a secret rotation, list both secrets.
const SECRETS = ['whsec_PASTE_YOUR_SIGNING_SECRET'];
const TOLERANCE_SEC = 5 * 60;

const crypto = require('crypto'); // self-hosted n8n: NODE_FUNCTION_ALLOW_BUILTIN=crypto (n8n Cloud allows it)

let secrets = SECRETS;
try {
  // $env is blocked on n8n Cloud and where N8N_BLOCK_ENV_ACCESS_IN_NODE=true; the list above is used then
  if ($env.REELSAW_WEBHOOK_SECRET) secrets = $env.REELSAW_WEBHOOK_SECRET.split(',').map((s) => s.trim()).filter(Boolean);
} catch {}

const item = $input.first();
const headers = item.json.headers ?? {};
// The signature covers the exact bytes Reelsaw sent: the Webhook node keeps them with "Raw Body" on.
const body = item.binary?.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : JSON.stringify(item.json.body);

function check() {
  const id = headers['webhook-id'];
  const timestamp = headers['webhook-timestamp'];
  const signatures = headers['webhook-signature'];
  if (!id || !timestamp || !signatures) return 'Missing webhook-id, webhook-timestamp or webhook-signature header';
  if (secrets.length === 0 || secrets.some((s) => s.includes('PASTE'))) return 'No signing secret set in the Verify signature node';
  const ts = Number(timestamp);
  if (!Number.isInteger(ts)) return 'webhook-timestamp is not a number';
  const now = Math.floor(Date.now() / 1000);
  if (now - ts > TOLERANCE_SEC) return 'Delivery is older than 5 minutes (a replay, or this clock is off)';
  if (ts - now > TOLERANCE_SEC) return 'Delivery is more than 5 minutes in the future (this clock is off)';
  const signed = Buffer.from(`${id}.${timestamp}.${body}`, 'utf8');
  const expected = secrets.map((s) => crypto.createHmac('sha256', Buffer.from(s.replace(/^whsec_/, ''), 'base64')).update(signed).digest());
  // several "v1,<sig>" separated by spaces while Reelsaw signs with an old and a new secret
  for (const part of String(signatures).split(' ')) {
    const [version, sig] = part.split(',');
    if (version !== 'v1' || !sig) continue;
    const given = Buffer.from(sig, 'base64');
    if (expected.some((e) => e.length === given.length && crypto.timingSafeEqual(e, given))) return null;
  }
  return 'Signature does not match: check the signing secret';
}

const reason = check();
let event = null;
if (!reason) {
  try {
    event = JSON.parse(body);
  } catch {
    return [{ json: { valid: false, reason: 'Body is not JSON' } }];
  }
}
return [{ json: { valid: !reason, reason, webhookId: headers['webhook-id'] ?? null, event } }];

// One item per clip to publish: the video's best maxClipsPerVideo rendered clips at or above minScore. Skips the
// Send test delivery, other event types, projects another workflow started (metadata.workflow), and clips this
// workflow already handed on (a re-run sends project.done again; Resend in Reelsaw's delivery log sends it once more).
const s = $('Settings').first().json;
const event = $('Verify signature').first().json.event;
if (event.type !== s.publishOn) return [];
const metadata = event.metadata ?? {};
if (s.workflowTag && metadata.workflow !== s.workflowTag) return [];

const store = $getWorkflowStaticData('global'); // kept between production executions, not manual test runs
const posted = new Set(store.postedClipIds ?? []);
const clips = event.type === 'clip.done' ? [event.data.clip] : (event.data.clips ?? []);
const picked = clips
  .filter((c) => c && c.status === 'done' && c.shareUrl && (c.score ?? 0) >= s.minScore)
  .sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
  .slice(0, s.maxClipsPerVideo)
  .filter((c) => !posted.has(c.id))
  .sort((a, b) => a.index - b.index);
store.postedClipIds = [...posted, ...picked.map((c) => c.id)].slice(-2000);

const project = event.data.project;
return picked.map((c) => {
  const hashtags = (c.hashtags ?? []).map((h) => `#${h.replace(/^#/, '')}`);
  const caption = c.caption || c.hook || c.title;
  return {
    json: {
      projectId: project.id,
      projectTitle: project.title,
      projectUrl: project.url,
      metadata,
      clipId: c.id,
      title: c.title,
      caption,
      hashtags,
      text: s.addHashtags && hashtags.length ? `${caption}\n\n${hashtags.join(' ')}` : caption,
      shareUrl: c.shareUrl,
      thumbnailShareUrl: c.thumbnailShareUrl,
      durationSec: c.durationSec,
      score: c.score,
    },
  };
});

// One Buffer createPost per clip and channel (https://developers.buffer.com/examples/create-video-post.html).
// Buffer has no upload endpoint: it fetches the video from the share link when the post publishes, which for a
// queued post can be days later. Reelsaw's share links last 90 days by default; revoking one breaks queued posts.
const s = $('Settings').first().json;
const list = (v) => String(v ?? '').split(',').map((x) => x.trim()).filter((x) => x && !x.startsWith('YOUR_'));
const channels = [
  ...list(s.bufferChannelIds).map((id) => ({ id, youtube: false })),
  ...list(s.bufferYoutubeChannelIds).map((id) => ({ id, youtube: true })),
];
if (!channels.length) throw new Error('Set bufferChannelIds or bufferYoutubeChannelIds in the Settings node');

const mutation = `mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    ... on PostActionSuccess { post { id dueAt } }
    ... on MutationError { message }
  }
}`;
return $input.all().flatMap(({ json: clip }) =>
  channels.map((ch) => {
    const input = {
      channelId: ch.id,
      text: clip.text,
      schedulingType: 'automatic',
      mode: s.bufferMode,
      saveToDraft: s.bufferSaveToDraft,
      assets: [{ video: { url: clip.shareUrl } }],
    };
    // YouTube needs a title and a category on create (YoutubePostMetadataInput)
    if (ch.youtube) input.metadata = { youtube: { title: clip.title.slice(0, 100), categoryId: String(s.youtubeCategoryId) } };
    return { json: { ...clip, channelId: ch.id, body: { query: mutation, variables: { input } } } };
  }),
);

// Buffer answers 200 with { data: { createPost: { post } } } or a MutationError { message } (or GraphQL errors).
// A clip Buffer refused on every channel is forgotten by Pick clips, so Resend in Reelsaw's delivery log retries it.
// Failures fail the execution after the other posts went out, so one bad clip does not hold back the rest.
const results = $input.all().map((item, i) => {
  const post = $('Build Buffer post').all()[i].json;
  const r = item.json;
  const created = r.data?.createPost?.post ?? null;
  const error = created ? null : (r.error?.message ?? r.errors?.[0]?.message ?? r.data?.createPost?.message ?? 'No post in the answer');
  return { clipId: post.clipId, title: post.title, channelId: post.channelId, bufferPostId: created?.id ?? null, dueAt: created?.dueAt ?? null, error };
});
const posted = new Set(results.filter((r) => !r.error).map((r) => r.clipId));
const refused = new Set(results.filter((r) => r.error && !posted.has(r.clipId)).map((r) => r.clipId));
const store = $getWorkflowStaticData('global');
store.postedClipIds = (store.postedClipIds ?? []).filter((id) => !refused.has(id));

const failed = results.filter((r) => r.error);
if (failed.length) throw new Error(`Buffer refused ${failed.length} post(s):\n${failed.map((r) => `${r.title} → ${r.channelId}: ${r.error}`).join('\n')}`);
return results.map((r) => ({ json: r }));

// create_webhook answers { endpoint, secret }. The secret is shown only this once: paste it into the
// Verify signature node (or REELSAW_WEBHOOK_SECRET), then activate this workflow.
const r = $json;
if (r.error) throw new Error(`Reelsaw MCP error: ${r.error.message}`);
const text = r.result?.content?.[0]?.text ?? '';
if (r.result?.isError) throw new Error(`Reelsaw: ${text}`);
const { endpoint, secret } = JSON.parse(text);
return { json: { webhookId: endpoint.id, url: endpoint.url, events: endpoint.events, secret, next: 'Paste secret into the Verify signature node, save, and activate this workflow.' } };
